// Generates src/types/api/<slice>.ts from docs/design/<slice>/openapi.yaml with openapi-typescript (frontend.md §7 Types).
//   node scripts/gen-api.mjs          write the generated files (npm run gen:api; commit the result)
//   node scripts/gen-api.mjs --check  regenerate to a temp dir and fail on any difference (npm run gen:api:check)
// openapi-typescript drives the TypeScript compiler API, which the native TypeScript 7 package does not ship.
// The devDependency alias `typescript-compiler-api` (typescript 5.x) provides it: the resolve hook below sends
// openapi-typescript's `typescript` import there, so the project's own `tsc` stays on TypeScript 7.
// Why not a nested override (`"overrides": {"openapi-typescript": {"typescript": "5.9.3"}}`)? openapi-typescript
// declares `typescript` as a peerDependency, and npm always places a peer beside its dependent (here the root,
// which holds typescript 7), never under it: that override fails `npm install` with ERESOLVE ("peer overridden
// typescript@5.9.3 ... Conflicting peer dependency"). The root override `"typescript": "$typescript"` only
// silences that peer check; the alias is what actually supplies 5.x. `module.registerHooks` needs Node >= 22.15.
import { mkdtempSync, readFileSync, rmSync, writeFileSync, existsSync } from 'node:fs'
import { registerHooks } from 'node:module'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'

registerHooks({
  resolve(specifier, context, nextResolve) {
    const fromGenerator = context.parentURL?.includes('/node_modules/openapi-typescript/') ?? false
    return nextResolve(specifier === 'typescript' && fromGenerator ? 'typescript-compiler-api' : specifier, context)
  },
})
const { default: openapiTS, astToString } = await import('openapi-typescript')

const FRONTEND_URL = new URL('../', import.meta.url)
const FRONTEND = fileURLToPath(FRONTEND_URL)
const SPECS = [
  { spec: '../docs/design/01-foundation/openapi.yaml', out: 'src/types/api/01-foundation.ts' },
  { spec: '../docs/design/02-customer/openapi.yaml', out: 'src/types/api/02-customer.ts' },
  { spec: '../docs/design/03-inbound/openapi.yaml', out: 'src/types/api/03-inbound.ts' },
]
const BANNER = (spec) =>
  `// Generated by scripts/gen-api.mjs (openapi-typescript) from ${spec.replace('../', '')}. Do not edit; run npm run gen:api.\n\n`

async function generate({ spec }) {
  const ast = await openapiTS(new URL(spec, FRONTEND_URL))
  return BANNER(spec) + astToString(ast)
}

const check = process.argv.includes('--check')
let drift = 0
const tmp = check ? mkdtempSync(join(tmpdir(), 'gen-api-')) : null
try {
  for (const entry of SPECS) {
    const target = join(FRONTEND, entry.out)
    const generated = await generate(entry)
    if (!check) {
      writeFileSync(target, generated)
      console.log(`gen:api: wrote ${entry.out}`)
      continue
    }
    const fresh = join(tmp, entry.out.replaceAll('/', '_'))
    writeFileSync(fresh, generated)
    const committed = existsSync(target) ? readFileSync(target, 'utf8') : null
    const regenerated = readFileSync(fresh, 'utf8')
    if (committed === regenerated) {
      console.log(`gen:api:check: ${entry.out} is up to date`)
      continue
    }
    drift++
    if (committed === null) {
      console.error(`gen:api:check: FAIL ${entry.out} is missing`)
      continue
    }
    const a = committed.split('\n')
    const b = regenerated.split('\n')
    const line = a.findIndex((text, i) => text !== b[i])
    const at = line === -1 ? a.length : line
    console.error(`gen:api:check: FAIL ${entry.out} differs from ${entry.spec} (first difference at line ${at + 1})`)
    console.error(`  committed:   ${a[at] ?? '<end of file>'}`)
    console.error(`  regenerated: ${b[at] ?? '<end of file>'}`)
  }
} finally {
  if (tmp) rmSync(tmp, { recursive: true, force: true })
}
if (drift > 0) {
  console.error('gen:api:check: run `npm run gen:api` and commit the result')
  process.exit(1)
}
